'use client'

import { useState } from 'react'
import { supabase } from '@/lib/supabase'
import { Send, CheckCircle, AlertCircle } from 'lucide-react'
import MainMenu from '@/components/MainMenu'

export default function Contribuer() {
  const [formData, setFormData] = useState({
    nomLieu: '',
    typesDeLieux: '',
    ville: '',
    description: '',
    email: ''
  })
  const [status, setStatus] = useState(null) // 'success', 'error', null
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!formData.nomLieu || !formData.typesDeLieux || !formData.ville) {
      setStatus('error')
      return
    }

    setLoading(true)

    try {
      const { error } = await supabase
        .from('contributions')
        .insert([{
          nom_lieu: formData.nomLieu,
          types_de_lieux: formData.typesDeLieux,
          ville: formData.ville,
          description: formData.description,
          email: formData.email,
          statut: 'en_attente',
          created_at: new Date().toISOString()
        }])

      if (error) throw error

      setStatus('success')
      setFormData({
        nomLieu: '',
        typesDeLieux: '',
        ville: '',
        description: '',
        email: ''
      })
    } catch (error) {
      console.error('Erreur:', error)
      setStatus('error')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4">
      <div className="w-[95%] max-w-4xl mx-auto">
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-800 mb-2">Contribuer à Hexa Index</h1>
            <p className="text-gray-600">
              Vous connaissez une ressource qui n'est pas encore référencée ? Proposez-la !
            </p>
            <div className="mt-4">
              <MainMenu />
            </div>
          </div>

          {status === 'success' && (
            <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6 flex items-start gap-3">
              <CheckCircle className="text-green-600 mt-0.5" size={20} />
              <div>
                <h3 className="font-semibold text-green-800">Contribution envoyée !</h3>
                <p className="text-sm text-green-700 mt-1">
                  Merci pour votre contribution. Elle sera examinée et ajoutée prochainement.
                </p>
              </div>
            </div>
          )}

          {status === 'error' && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6 flex items-start gap-3">
              <AlertCircle className="text-red-600 mt-0.5" size={20} />
              <div>
                <h3 className="font-semibold text-red-800">Erreur</h3>
                <p className="text-sm text-red-700 mt-1">
                  Veuillez remplir tous les champs obligatoires.
                </p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium mb-2">
                Nom du lieu <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={formData.nomLieu}
                onChange={(e) => setFormData({ ...formData, nomLieu: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Ex: Atelier Supersérigraphie"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Type(s) de lieu <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={formData.typesDeLieux}
                onChange={(e) => setFormData({ ...formData, typesDeLieux: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Ex: Sérigraphie, Atelier d'impression"
                required
              />
              <p className="text-xs text-gray-500 mt-1">
                Séparez plusieurs types par des virgules
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Ville <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={formData.ville}
                onChange={(e) => setFormData({ ...formData, ville: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Ex: Lyon"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Description / Informations complémentaires
              </label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent min-h-[120px]"
                placeholder="Ajoutez des détails utiles : adresse, site web, horaires, spécialités..."
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Votre email (optionnel)
              </label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="votre@email.com"
              />
              <p className="text-xs text-gray-500 mt-1">
                Pour être tenu au courant de l'ajout de votre contribution
              </p>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 flex items-center justify-center gap-2 disabled:bg-gray-400 disabled:cursor-not-allowed font-medium"
            >
              {loading ? (
                'Envoi en cours...'
              ) : (
                <>
                  <Send size={20} />
                  Envoyer la contribution
                </>
              )}
            </button>
          </form>
        </div>

        <div className="bg-blue-50 border border-blue-200 rounded-lg p-6">
          <h3 className="font-semibold text-blue-900 mb-2">Pourquoi contribuer ?</h3>
          <p className="text-sm text-blue-800">
            Hexa Index est une base collaborative qui vit grâce aux contributions de la communauté. 
            En partageant vos découvertes, vous aidez d'autres graphistes à trouver les ressources 
            dont ils ont besoin partout en France !
          </p>
        </div>
      </div>
    </div>
  )
}